window.STUDY_DATA = {
  categories: ["全部", "图解网络", "图解系统", "C++ 面试篇", "计算机基础面试篇", "工具命令面试篇", "CUDA 面试篇"],
  questions: [
    {id:"net-01", category:"图解网络", q:"TCP 为什么需要三次握手，而不是两次？", options:["为了传输更多数据","为了让双方确认收发能力并避免失效连接请求造成误连接","为了给数据加密","为了分配 MAC 地址"], answer:1, why:"三次握手能让客户端和服务端都确认自己的发送、接收能力正常，并防止历史失效连接请求导致服务端误建立连接。"},
    {id:"net-02", category:"图解网络", q:"主动关闭 TCP 连接的一方为什么通常会进入 TIME_WAIT？", options:["等待应用程序退出","保证最后一个 ACK 可重传，并让旧连接报文在网络中消失","等待 DNS 解析","限制接收窗口"], answer:1, why:"TIME_WAIT 主要保证对端若重传 FIN，主动关闭方仍能再次发送 ACK，同时避免旧报文影响相同四元组的新连接。"},
    {id:"net-03", category:"图解网络", q:"TCP 流量控制主要依靠什么机制？", options:["接收窗口","IP 分片","ARP 缓存","端口复用"], answer:0, why:"接收方通过通告接收窗口告诉发送方自己还能接收多少数据，防止发送速度超过接收能力。"},
    {id:"net-04", category:"图解网络", q:"TCP 拥塞控制中的慢启动，拥塞窗口通常如何增长？", options:["保持不变","每个 RTT 近似指数增长","每秒减少一半","只由接收窗口决定"], answer:1, why:"慢启动阶段每收到确认会扩大拥塞窗口，因此一个 RTT 内通常近似翻倍，直到到达阈值或检测到拥塞。"},
    {id:"net-05", category:"图解网络", q:"DNS 解析的核心作用是什么？", options:["把域名转换为 IP 地址","把 IP 地址转换为 MAC 地址","为 TCP 分配序列号","加密 HTTP 报文"], answer:0, why:"DNS 是分布式域名系统，负责查询域名所对应的 IP 地址及其他资源记录。"},
    {id:"net-06", category:"图解网络", q:"ARP 在 IPv4 局域网中的作用是什么？", options:["域名解析","根据目标 IPv4 地址查询 MAC 地址","建立 TCP 连接","选择应用层协议"], answer:1, why:"主机在同一链路发送以太网帧前，需要通过 ARP 得到目标 IP 或网关 IP 对应的 MAC 地址。"},
    {id:"net-07", category:"图解网络", q:"TCP 是字节流协议，这会给应用层带来什么常见问题？", options:["无法重传","粘包与拆包，需要应用层定义消息边界","不能双向通信","不能使用端口"], answer:1, why:"TCP 不保留应用写入时的消息边界，应用层通常要通过固定长度、分隔符或长度字段完成拆包。"},
    {id:"net-08", category:"图解网络", q:"HTTPS 相比 HTTP，主要增加了哪一层能力？", options:["TLS 加密、身份认证和完整性保护","更大的 IP 地址","自动数据库索引","取消 TCP 握手"], answer:0, why:"HTTPS 通常是在 HTTP 与 TCP 之间使用 TLS，以提供加密、证书认证和报文完整性校验。"},
    {id:"net-09", category:"图解网络", q:"UDP 更适合下面哪类场景？", options:["必须可靠且严格有序的文件传输","追求低延迟并能容忍少量丢包的实时通信","要求连接建立后才能发送","必须由协议自动重传"], answer:1, why:"UDP 无连接、首部开销小，常用于实时音视频、游戏和允许应用层自行控制可靠性的场景。"},
    {id:"net-10", category:"图解网络", q:"路由器转发 IP 数据包时，主要依据什么信息？", options:["目标 IP 与路由表","源进程名称","HTTP 状态码","文件描述符"], answer:0, why:"路由器根据目标 IP 地址进行最长前缀匹配，从路由表选出下一跳和出口接口。"},

    {id:"os-01", category:"图解系统", q:"进程与线程最核心的区别是什么？", options:["线程拥有独立地址空间","同一进程内线程共享地址空间和大部分资源","进程不能并发","线程不能被调度"], answer:1, why:"进程是资源分配的基本单位，同一进程内线程共享地址空间、文件等资源，但各自拥有栈和寄存器上下文。"},
    {id:"os-02", category:"图解系统", q:"一次缺页异常发生后，操作系统通常要做什么？", options:["立即结束进程","把所需页面调入物理内存并更新页表","清空全部缓存","重新编译程序"], answer:1, why:"访问的虚拟页不在内存时会触发缺页异常，内核装入页面、更新页表后让指令继续执行。"},
    {id:"os-03", category:"图解系统", q:"虚拟内存给进程带来的主要好处是什么？", options:["每个进程看到独立连续的地址空间，并获得隔离与按需分页","取消物理内存","保证程序永不缺页","让磁盘等同于 CPU 缓存"], answer:0, why:"虚拟内存通过页表建立虚拟地址到物理地址的映射，实现地址空间隔离、按需分配和更灵活的内存管理。"},
    {id:"os-04", category:"图解系统", q:"形成死锁必须同时满足的条件中，不包括哪一项？", options:["互斥","请求并保持","不可剥夺","所有线程优先级相同"], answer:3, why:"死锁的四个必要条件是互斥、请求并保持、不可剥夺和循环等待，与线程优先级是否相同无关。"},
    {id:"os-05", category:"图解系统", q:"互斥锁与信号量的典型区别是什么？", options:["二者完全相同","互斥锁强调所有权，信号量可表示多个可用资源","信号量只能用于进程外","互斥锁可以无限计数"], answer:1, why:"互斥锁通常由加锁线程解锁，用于互斥访问；计数信号量可描述若干资源，并用于同步或限流。"},
    {id:"os-06", category:"图解系统", q:"用户态程序发起系统调用时，CPU 会发生什么变化？", options:["切换到内核态执行受保护的内核服务","切换到另一台计算机","关闭中断直到进程退出","直接修改内核代码"], answer:0, why:"系统调用通过受控入口从用户态切换到内核态，内核完成文件、网络、进程等特权操作后再返回。"},
    {id:"os-07", category:"图解系统", q:"上下文切换通常需要保存和恢复什么？", options:["仅文件名","寄存器、程序计数器和栈等执行现场","所有磁盘数据","源代码"], answer:1, why:"调度器切换任务时要保存当前执行上下文，并恢复下一个任务的寄存器和执行位置。"},
    {id:"os-08", category:"图解系统", q:"零拷贝技术主要想减少什么开销？", options:["网络连接数量","用户态与内核态之间不必要的数据复制和上下文切换","线程数量","文件大小"], answer:1, why:"sendfile、mmap 等机制可减少数据在用户缓冲区与内核缓冲区间的复制，从而降低 CPU 和内存带宽开销。"},
    {id:"os-09", category:"图解系统", q:"LRU 页面置换算法优先淘汰哪一页？", options:["最近最常使用的页","最长时间未被访问的页","地址最大的页","刚刚调入的页"], answer:1, why:"LRU 利用时间局部性，选择最久没有被访问的页面作为淘汰候选。"},
    {id:"os-10", category:"图解系统", q:"epoll 相比 select 的一个典型优势是什么？", options:["只能监听一个文件描述符","无需每次线性扫描全部文件描述符，适合大量连接","不需要内核参与","只能用于普通文件"], answer:1, why:"epoll 由内核维护关注集合并返回就绪事件，避免每次复制和遍历完整描述符集合。"},

    {id:"cpp-01", category:"C++ 面试篇", q:"通过基类指针删除派生类对象时，基类析构函数为什么应为 virtual？", options:["提高编译速度","保证派生类析构与基类析构都被正确调用","禁止对象创建","让成员自动变成 static"], answer:1, why:"虚析构允许动态绑定析构过程，否则通过基类指针 delete 可能无法完整释放派生类资源。"},
    {id:"cpp-02", category:"C++ 面试篇", q:"RAII 的核心思想是什么？", options:["资源生命周期绑定对象生命周期","所有资源都用全局变量保存","只在 main 中释放资源","通过宏管理内存"], answer:0, why:"RAII 在对象构造时获取资源、析构时释放资源，利用作用域保证异常路径也能正确清理。"},
    {id:"cpp-03", category:"C++ 面试篇", q:"vector 扩容后，原有迭代器为什么可能失效？", options:["元素自动变成 const","底层连续内存可能重新分配并搬迁元素","vector 改成链表","编译器删除迭代器"], answer:1, why:"容量不足时 vector 会申请新连续空间并移动或复制元素，旧地址上的指针、引用和迭代器随之失效。"},
    {id:"cpp-04", category:"C++ 面试篇", q:"shared_ptr 循环引用通常如何解决？", options:["把其中一方改为 weak_ptr","重复调用 delete","改用裸指针并永不释放","增加引用计数"], answer:0, why:"weak_ptr 不增加强引用计数，可打破对象之间的 shared_ptr 环并安全观察对象是否仍存在。"},
    {id:"cpp-05", category:"C++ 面试篇", q:"std::move 本身实际做了什么？", options:["立即搬走对象资源","把表达式转换成可触发移动语义的右值类别","销毁原对象","分配一块新内存"], answer:1, why:"std::move 本质上是类型转换；真正的资源转移由随后调用的移动构造或移动赋值完成。"},
    {id:"cpp-06", category:"C++ 面试篇", q:"深拷贝与浅拷贝的关键区别是什么？", options:["深拷贝只复制指针值","深拷贝为资源分配独立存储并复制内容","浅拷贝一定更慢","二者没有区别"], answer:1, why:"对象拥有动态资源时，深拷贝创建独立资源，避免多个对象共享同一地址造成相互影响或重复释放。"},
    {id:"cpp-07", category:"C++ 面试篇", q:"unordered_map 的平均查询复杂度通常是多少？", options:["O(1)","O(log n)","O(n log n)","O(n²)"], answer:0, why:"哈希分布良好时查询平均为 O(1)，但大量冲突等极端情况下最坏可退化为 O(n)。"},
    {id:"cpp-08", category:"C++ 面试篇", q:"下面哪一种成员函数不能直接访问 this 指针？", options:["const 成员函数","虚函数","静态成员函数","析构函数"], answer:2, why:"静态成员函数属于类而不依赖具体对象，因此没有隐式 this 指针。"},
    {id:"cpp-09", category:"C++ 面试篇", q:"std::jthread 相比 std::thread 的主要改进是什么？", options:["只能运行一次","析构时自动请求停止并 join","不允许传递参数","始终分离线程"], answer:1, why:"jthread 提供 RAII 式 join，并集成 stop_token 协作式停止，降低忘记 join 导致程序终止的风险。"},
    {id:"cpp-10", category:"C++ 面试篇", q:"运行时多态通常依赖什么机制实现？", options:["函数宏","虚函数、虚表与动态绑定","模板特化","命名空间"], answer:1, why:"通过基类指针或引用调用虚函数时，程序会依据对象的动态类型选择派生类实现。"},

    {id:"cs-01", category:"计算机基础面试篇", q:"二分查找成立的基本前提是什么？", options:["数据必须有序且支持定位中间元素","数据必须无序","只能使用链表","元素必须全部不同"], answer:0, why:"二分查找依赖有序性判断目标落在哪一半，在数组等支持随机访问的结构上最常用。"},
    {id:"cs-02", category:"计算机基础面试篇", q:"快速排序的平均时间复杂度是多少？", options:["O(1)","O(log n)","O(n log n)","O(n²)"], answer:2, why:"划分较均匀时递归约 log n 层，每层处理 n 个元素；最坏情况下会退化为 O(n²)。"},
    {id:"cs-03", category:"计算机基础面试篇", q:"广度优先搜索通常使用哪种数据结构维护待访问节点？", options:["栈","队列","最小堆","并查集"], answer:1, why:"BFS 按层扩展节点，队列的先进先出顺序能保证先发现的节点先处理。"},
    {id:"cs-04", category:"计算机基础面试篇", q:"哈希表发生冲突时，常见的处理方法是什么？", options:["链地址法或开放寻址法","删除全部元素","把键改成数组下标","禁止插入"], answer:0, why:"不同键映射到同一位置时，可通过桶内链表等链地址法，或探测其他位置的开放寻址法解决。"},
    {id:"cs-05", category:"计算机基础面试篇", q:"Dijkstra 算法不能直接处理哪类图？", options:["有向图","无向图","含负权边的图","稀疏图"], answer:2, why:"Dijkstra 的贪心选择依赖边权非负，存在负权边时应考虑 Bellman-Ford 等算法。"},
    {id:"cs-06", category:"计算机基础面试篇", q:"数组相比链表，通常具有哪项优势？", options:["任意位置插入总是 O(1)","连续存储带来高效随机访问和更好的缓存局部性","不需要内存空间","长度永远可变"], answer:1, why:"数组连续存储，可按下标 O(1) 访问，并能更好利用 CPU cache；中间插入删除则可能需要搬移元素。"},
    {id:"cs-07", category:"计算机基础面试篇", q:"小端序机器如何存放一个多字节整数？", options:["高位字节放低地址","低位字节放低地址","所有字节放同一地址","按字符顺序随机存放"], answer:1, why:"小端序把数值的最低有效字节放在最低内存地址，高端序则相反。"},
    {id:"cs-08", category:"计算机基础面试篇", q:"CPU Cache 利用空间局部性的典型方式是什么？", options:["每次只读取一个比特","以缓存行一次加载相邻的一段内存","关闭预取","把所有数据写入磁盘"], answer:1, why:"程序访问某地址后往往还会访问附近地址，因此缓存按 cache line 搬运连续数据可提高命中率。"},
    {id:"cs-09", category:"计算机基础面试篇", q:"栈与队列的访问顺序分别是什么？", options:["栈 FIFO，队列 LIFO","栈 LIFO，队列 FIFO","二者都是随机访问","二者都是优先级访问"], answer:1, why:"栈后进先出，队列先进先出，适用于不同的算法和任务调度场景。"},
    {id:"cs-10", category:"计算机基础面试篇", q:"平衡二叉搜索树查找的典型时间复杂度是多少？", options:["O(1)","O(log n)","O(n²)","O(2ⁿ)"], answer:1, why:"保持树高为 O(log n) 后，查找、插入和删除都只需沿一条根到叶的路径进行。"},

    {id:"tool-01", category:"工具命令面试篇", q:"git fetch 与 git pull 的主要区别是什么？", options:["fetch 会删除远程分支","pull 通常会在 fetch 后继续合并或变基","fetch 会直接覆盖工作区","两者完全相同"], answer:1, why:"fetch 只获取远程对象并更新远程跟踪分支，pull 还会把远程变化整合到当前分支。"},
    {id:"tool-02", category:"工具命令面试篇", q:"Git 中 rebase 的主要作用是什么？", options:["删除仓库","把一组提交重新应用到新的基点上","创建二进制文件","清空暂存区"], answer:1, why:"rebase 可把当前分支提交移到新的基点，形成较线性的历史，但不宜随意改写已共享的公共提交。"},
    {id:"tool-03", category:"工具命令面试篇", q:"Docker 镜像与容器是什么关系？", options:["镜像是只读模板，容器是它的运行实例","容器是镜像的源码","二者都只能运行一次","镜像必须依赖正在运行的容器"], answer:0, why:"镜像由只读层组成，容器在镜像之上增加可写层并拥有自己的进程和运行状态。"},
    {id:"tool-04", category:"工具命令面试篇", q:"Dockerfile 中 FROM 指令的作用是什么？", options:["指定基础镜像","复制文件到宿主机","查看容器日志","停止所有容器"], answer:0, why:"FROM 声明构建阶段所基于的镜像，是大多数 Dockerfile 的起点。"},
    {id:"tool-05", category:"工具命令面试篇", q:"Linux 中查看进程列表常用哪个命令？", options:["ps","cp","mkdir","chmod"], answer:0, why:"ps 用于查看进程快照，常与 aux、-ef 等参数组合；top 可动态查看进程状态。"},
    {id:"tool-06", category:"工具命令面试篇", q:"chmod 755 file 中，755 分别表示什么权限？", options:["所有人都可写","所有者 rwx，组和其他用户 r-x","所有者只读，其他用户可写","删除文件权限"], answer:1, why:"7 是读写执行，5 是读和执行，因此 755 表示所有者 rwx、同组和其他用户 r-x。"},
    {id:"tool-07", category:"工具命令面试篇", q:"GDB 中 step 与 next 的主要区别是什么？", options:["step 会进入函数，next 通常越过函数调用","next 会退出调试器","step 只能查看变量","二者都用于设置断点"], answer:0, why:"step 单步时会进入有调试信息的被调函数，next 则通常把函数调用作为当前行的一部分执行完。"},
    {id:"tool-08", category:"工具命令面试篇", q:"CMake 中 add_executable 的作用是什么？", options:["定义一个可执行构建目标","安装操作系统","创建 Git 分支","启动 Docker 容器"], answer:0, why:"add_executable 根据指定源文件创建可执行目标，后续可为该目标配置头文件路径、链接库和编译选项。"},
    {id:"tool-09", category:"工具命令面试篇", q:"Linux 管道符 `|` 的作用是什么？", options:["把前一个命令的标准输出连接到后一个命令的标准输入","并行启动两台机器","修改文件权限","创建硬链接"], answer:0, why:"管道让多个命令组合处理数据，前一进程的输出通过内核管道成为后一进程的输入。"},
    {id:"tool-10", category:"工具命令面试篇", q:"Docker 数据卷相对容器可写层的主要价值是什么？", options:["让数据独立于容器生命周期并便于共享","让镜像变得不可下载","禁止容器访问文件","自动编译程序"], answer:0, why:"volume 由 Docker 独立管理，容器删除后数据仍可保留，也可挂载给多个容器使用。"},

    {id:"cuda-01", category:"CUDA 面试篇", q:"当前主流 NVIDIA GPU 中，一个 Warp 通常包含多少个线程？", options:["8","16","32","64"], answer:2, why:"CUDA 的 Warp 通常由 32 个线程组成，Warp 是 GPU 调度和执行线程的基本单位。"},
    {id:"cuda-02", category:"CUDA 面试篇", q:"什么样的全局内存访问更容易形成合并访问？", options:["相邻线程访问相邻且对齐的地址","所有线程访问随机地址","每个线程跨越很大的不同步长","只让一个线程访问"], answer:0, why:"同一 Warp 的线程访问连续、对齐的内存区域时，硬件可用更少的内存事务完成请求。"},
    {id:"cuda-03", category:"CUDA 面试篇", q:"Shared Memory 的 Bank Conflict 是什么？", options:["多个线程访问显存容量不足","同一 Warp 中多个线程对同一 bank 的不同地址发起访问而产生串行化","线程块数量过少","GPU 与 CPU 不兼容"], answer:1, why:"共享内存分为多个 bank，同一 Warp 对同一 bank 的不同地址访问通常要拆分处理，广播等特例除外。"},
    {id:"cuda-04", category:"CUDA 面试篇", q:"__syncthreads() 能同步哪些线程？", options:["整个 Grid 的全部线程","同一个线程块内的线程","同一台机器上的全部进程","仅 CPU 线程"], answer:1, why:"__syncthreads 是线程块级屏障，不能直接作为跨 Block 的全局同步手段。"},
    {id:"cuda-05", category:"CUDA 面试篇", q:"寄存器使用过多可能导致什么性能问题？", options:["一定提高 Occupancy","寄存器溢出到 Local Memory，或限制同时驻留的线程块","自动增加显存带宽","消除线程分歧"], answer:1, why:"每个 SM 的寄存器总量有限，单线程使用过多会降低占用率；超过分配能力还可能发生 register spilling。"},
    {id:"cuda-06", category:"CUDA 面试篇", q:"CUDA Stream 的主要用途是什么？", options:["描述线程块形状","组织异步操作，并在条件允许时实现计算与传输重叠","替代所有显存","设置 CPU 主频"], answer:1, why:"不同非默认 Stream 中无依赖的操作可能并发执行，配合异步拷贝和页锁定内存可实现流水重叠。"},
    {id:"cuda-07", category:"CUDA 面试篇", q:"Warp 分支分化为什么会降低性能？", options:["不同分支路径可能被分批执行，降低活跃线程比例","它会改变显存容量","它会关闭 GPU","它只影响编译时间"], answer:0, why:"同一 Warp 的线程走不同控制流路径时，硬件往往需要分别执行各路径并屏蔽不参与的线程。"},
    {id:"cuda-08", category:"CUDA 面试篇", q:"提高 CUDA Kernel 算术强度通常意味着什么？", options:["每搬运一个字节完成更多计算","只增加线程数量","减少所有算术指令","把数据全部放入 CPU"], answer:0, why:"算术强度是计算量与数据搬运量的比值，提高数据复用可让程序更可能从内存带宽受限转为计算受限。"},
    {id:"cuda-09", category:"CUDA 面试篇", q:"Tensor Core 主要用于加速哪类运算？", options:["矩阵乘加","文件系统调用","字符串排序","网络握手"], answer:0, why:"Tensor Core 针对低精度及混合精度矩阵乘加提供高吞吐，是深度学习和高性能 GEMM 的重要单元。"},
    {id:"cuda-10", category:"CUDA 面试篇", q:"优化 Reduction 时，为什么常使用 Warp Shuffle？", options:["在线程间交换寄存器数据，减少共享内存和同步开销","分配更多 CPU 内存","把核函数改成串行","创建新的 CUDA Context"], answer:0, why:"Warp Shuffle 允许同一 Warp 内线程直接交换寄存器值，适合规约末段并可减少共享内存访问。"},

    {id:"net-s01", type:"short", category:"图解网络", q:"请说明 TCP 如何通过序列号、确认、重传和滑动窗口实现可靠传输。", points:["序列号标识字节位置，接收方通过 ACK 告知已连续收到的位置","超时重传和快速重传处理丢包，重复 ACK 可辅助判断缺口","滑动窗口允许多个报文在途，并同时受接收窗口和拥塞窗口约束","可靠只保证连接内有序字节流，不替应用层定义消息边界"], sample:"TCP 给字节编号，接收端用累计 ACK 确认连续数据；发送端依据超时或重复 ACK 重传缺失段。滑动窗口让多个段并行在途，窗口上限同时受接收能力和拥塞状态限制，最终向应用提供有序、无重复的字节流。"},
    {id:"net-s02", type:"short", category:"图解网络", q:"如果要设计实时音视频传输，你会如何在 TCP 和 UDP 之间做选择？", points:["先说明延迟、丢包容忍度、顺序和带宽约束，而不是直接背结论","UDP 适合低延迟和应用层自定义重传、纠错、拥塞控制的场景","TCP 适合不能接受缺失且可容忍队头阻塞的传输","实际系统可能组合使用，例如信令走 TCP、媒体走 UDP"], sample:"我会先看业务能否容忍少量丢包以及是否更怕延迟。实时媒体通常选择 UDP，并在应用层增加序号、抖动缓冲、选择性重传或 FEC；控制信令和必须可靠的数据可以走 TCP。这样避免 TCP 丢包后的队头阻塞拖慢实时播放。"},
    {id:"net-s03", type:"short", category:"图解网络", q:"线上出现“连接偶尔很慢”，你会按什么顺序定位是 DNS、建连、TLS 还是服务处理问题？", points:["把总耗时拆成 DNS、TCP connect、TLS handshake、TTFB 和下载阶段","结合客户端时间线、服务端日志和链路抓包交叉验证","查看丢包重传、RTT、连接池复用、证书校验和服务端排队","先用数据确定慢在哪一段，再针对具体层级排查"], sample:"我会先用 curl 时间指标或客户端埋点拆分 DNS、TCP、TLS、首字节和下载耗时，再与服务端请求日志对齐。如果 connect 慢就看 RTT、丢包和 SYN 重传；TLS 慢看会话复用和证书链；TTFB 慢再查服务端排队、依赖和计算。"},
    {id:"net-s04", type:"short", category:"图解网络", q:"HTTP 长连接、连接池和多路复用分别解决什么问题？", points:["长连接减少重复 TCP/TLS 建连成本","连接池复用并限制到同一目标的连接数量，管理空闲与超时","HTTP/2 多路复用让多个请求共享一条连接并用流区分","需要说明队头阻塞、连接竞争和故障隔离等取舍"], sample:"长连接让请求复用已建立的 TCP/TLS 通道；连接池负责保存、借还和限制这些连接；HTTP/2 多路复用进一步在一条连接内并发多个流。它们都减少建连开销，但仍要处理连接级故障、拥塞和服务端容量限制。"},

    {id:"os-s01", type:"short", category:"图解系统", q:"进程、线程和协程在资源、调度和切换成本上有什么区别？", points:["进程拥有独立地址空间，隔离强但通信和切换成本较高","同一进程线程共享地址空间，由内核调度，需处理同步与竞态","协程通常在用户态协作调度，切换轻但阻塞调用可能影响执行器","选择取决于隔离、并行、I/O 模型和故障边界"], sample:"进程以独立地址空间提供强隔离；线程共享进程资源并由内核调度，能利用多核但要同步共享状态；协程通常由运行时在用户态切换，适合大量 I/O 任务，但需要非阻塞生态。实际选择要看隔离、并行度和开发复杂度。"},
    {id:"os-s02", type:"short", category:"图解系统", q:"mmap 读取大文件与 read 读取相比有哪些优势和风险？", points:["mmap 把文件页映射到虚拟地址，可减少显式拷贝和简化随机访问","真正 I/O 仍由缺页触发，不等于文件立即进入内存","需要处理页错误、地址空间占用、文件截断与 SIGBUS","顺序流式读取时 read 配合缓冲可能更可控"], sample:"mmap 适合随机访问和把文件当内存结构使用，内核按需装页，省去用户缓冲区中的显式 read 循环。但缺页延迟可能抖动，映射期间文件被截断还可能触发 SIGBUS；纯顺序读取时 read 加合理缓冲往往更简单。"},
    {id:"os-s03", type:"short", category:"图解系统", q:"你会如何定位一个疑似死锁的问题？", points:["先确认线程是否长期无进展，而不是单纯运行缓慢","获取线程栈和锁等待关系，构建等待图寻找环","检查锁顺序、持锁范围、条件变量谓词和异常退出路径","修复可采用统一锁顺序、缩小临界区、scoped_lock 或超时监控"], sample:"我会先抓取所有线程栈，确认它们分别阻塞在哪把锁上，再根据“线程持有什么、又等待什么”画等待图。如果存在环，就回到代码检查锁顺序和异常路径；通常通过统一加锁顺序或一次性锁住多把锁消除循环等待。"},
    {id:"os-s04", type:"short", category:"图解系统", q:"管道、共享内存、消息队列和 Socket 分别适合什么进程间通信场景？", points:["管道简单，适合有亲缘关系或命令流水线的字节流","共享内存吞吐高，但需要额外同步并管理数据一致性","消息队列保留消息边界，适合异步解耦但有复制和容量成本","Socket 可跨主机且接口统一，代价是协议和序列化开销"], sample:"小规模父子进程流式传输可以用管道；同机大数据高吞吐适合共享内存加信号量或锁；需要消息边界和异步排队时用消息队列；可能跨机器或希望统一通信接口时用 Socket。"},

    {id:"cpp-s01", type:"short", category:"C++ 面试篇", q:"请解释 RAII 如何同时解决资源管理和异常安全问题。", points:["把资源获取绑定到对象构造，把释放绑定到析构","栈展开时析构函数仍会执行，覆盖正常返回和异常路径","使用 unique_ptr、lock_guard、vector 等拥有明确所有权的类型","析构函数不应抛异常，复杂提交可配合事务式设计"], sample:"RAII 把文件、内存、锁等资源封装成对象，构造成功表示资源有效，析构无条件释放。发生异常时栈展开仍会调用已构造对象的析构函数，因此不需要在每个 return 或 catch 中手工清理。"},
    {id:"cpp-s02", type:"short", category:"C++ 面试篇", q:"std::vector 扩容时会发生什么，哪些迭代器或引用会失效？", points:["容量不足时申请更大的连续内存并移动或复制已有元素","旧内存释放后，原有迭代器、指针和引用全部失效","未扩容的尾部插入通常只使 end 及之后相关位置失效，具体看操作规则","可用 reserve、索引或稳定地址容器降低风险"], sample:"vector 必须保持连续存储，容量不足时会申请新区域并移动元素，然后释放旧区域，所以所有指向旧元素的指针、引用和迭代器都会失效。已知规模时先 reserve，可以减少扩容和失效次数。"},
    {id:"cpp-s03", type:"short", category:"C++ 面试篇", q:"为什么通过基类指针删除派生对象时，基类析构函数通常要声明为 virtual？", points:["删除表达式需要按动态类型调用完整析构链","非虚析构通过基类指针 delete 派生对象会产生未定义行为","多态基类通常应使用 public virtual 析构，或使用 protected 非虚析构禁止外部删除","同时说明对象所有权最好交给智能指针表达"], sample:"如果对象实际类型是派生类，而 delete 只静态地调用基类非虚析构，就无法保证派生部分正确销毁，行为未定义。面向多态删除的基类应提供虚析构，并尽量用 unique_ptr<Base> 等类型表达所有权。"},
    {id:"cpp-s04", type:"short", category:"C++ 面试篇", q:"设计一个线程池时，需要重点考虑哪些并发、生命周期和关闭语义？", points:["任务队列需要互斥与条件变量，并用谓词处理虚假唤醒","明确队列容量、背压、拒绝策略和任务异常传播","关闭要区分处理完剩余任务与立即取消，并唤醒所有等待线程","线程必须有序 join，任务和共享资源生命周期不能早于工作线程结束"], sample:"线程池不仅是线程加队列。我要定义提交后的所有权、队列是否有界、满载时如何背压，以及 stop 后是否排空任务。工作线程用带谓词的条件变量等待，关闭时设置状态、notify_all，最后由管理者统一 join。"},

    {id:"base-s01", type:"short", category:"计算机基础面试篇", q:"哈希表发生冲突时可以怎样处理？不同方案有什么取舍？", points:["拉链法用桶内链表或其他容器，删除简单但有额外指针和缓存成本","开放寻址把元素放在表内，缓存友好但对装载因子敏感","需要良好的哈希函数、扩容策略和装载因子控制","回答应结合查询、删除、内存和最坏情况"], sample:"常见方案是拉链法和开放寻址。拉链法实现直观、删除方便，但节点分散；开放寻址连续性更好，不过装载因子升高后探测变长。两者都需要控制装载因子并在必要时 rehash。"},
    {id:"base-s02", type:"short", category:"计算机基础面试篇", q:"面对近乎有序、数据量大且内存受限的输入，你会如何选择排序算法？", points:["先分析数据规模、稳定性、是否能全部装入内存和输入分布","近乎有序数据可考虑插入排序或能利用自然有序段的算法","内存受限且超大数据通常采用外部归并排序","不能只背时间复杂度，还要考虑常数、缓存、稳定性和最坏情况"], sample:"如果数据能放进内存且接近有序，插入排序在小规模或局部段上很有效；若数据远超内存，则应分块排序后做多路归并。算法选择需要同时看稳定性、额外空间、缓存局部性和最坏情况。"},
    {id:"base-s03", type:"short", category:"计算机基础面试篇", q:"BFS 和 DFS 分别适合解决什么问题？", points:["BFS 按层扩展，适合无权图最短步数和层序问题","DFS 深入一条路径，适合连通性、拓扑、回溯和结构遍历","BFS 通常需要队列并可能占较多宽度空间，DFS 需关注递归深度","有权最短路不能直接用普通 BFS"], sample:"BFS 保证按距离层次访问，因此适合无权图最短路；DFS 更适合枚举路径、判断连通、拓扑排序和回溯。选择时还要看图的宽度、深度以及是否存在边权。"},
    {id:"base-s04", type:"short", category:"计算机基础面试篇", q:"为什么连续数组遍历通常比链表遍历更快？", points:["数组连续存储具有更好的空间局部性和缓存行利用率","硬件预取器更容易预测连续访问","链表节点分散且每步依赖前一个指针，易产生缓存未命中","复杂度同为 O(n) 不代表实际常数和硬件效率相同"], sample:"数组元素连续，一个缓存行能带入多个后续元素，硬件也容易预取；链表每次需要先读指针才能知道下一个地址，节点分散会频繁缓存未命中。因此两者虽然都是线性遍历，实际性能可能差很多。"},

    {id:"tool-s01", type:"short", category:"工具命令面试篇", q:"Linux 服务器 CPU 使用率突然升高，你会如何定位？", points:["先用 top、pidstat 等确认进程、线程以及 user/system/iowait 构成","定位热点线程后获取调用栈，必要时使用 perf record/report","结合日志、请求量、上下文切换和系统调用判断根因","修复后用同一负载和指标验证，而不是只看瞬时 CPU 降低"], sample:"我会先确认是哪个进程和线程，以及 CPU 时间花在用户态、内核态还是 I/O 等待。随后用 pidstat 和 perf 找到热点函数，并结合请求量和日志判断是忙循环、锁竞争、系统调用还是业务计算，最后用相同负载回归验证。"},
    {id:"tool-s02", type:"short", category:"工具命令面试篇", q:"Git merge 和 rebase 有什么区别，团队中应如何选择？", points:["merge 保留分支历史并生成合并提交，不改写已有提交","rebase 把提交重放到新基线，历史线性但会改写提交哈希","已共享的公共分支通常不要随意 rebase","选择取决于团队历史策略、审查方式和冲突处理成本"], sample:"merge 保留真实分叉并产生合并提交；rebase 把自己的提交重放到目标分支，历史更线性但提交哈希会改变。我会在尚未共享的个人分支整理历史，公共分支则优先 merge，避免影响他人。"},
    {id:"tool-s03", type:"short", category:"工具命令面试篇", q:"Docker 容器出现内存持续增长，你会从哪些层面排查？", points:["先看容器限制、working set、cache 与是否发生 OOMKill","区分应用堆泄漏、原生内存、线程栈、文件缓存和共享内存","结合语言 Profiling、/proc、cgroup 指标与容器日志定位","需要设置合理 limit、健康检查和压力回归"], sample:"先确认 cgroup 限额和 OOM 记录，再区分 RSS、page cache 与应用堆。随后结合进程内存映射和对应语言的分析工具定位增长来源，并在固定流量下观察是否可回收，最后补充限制和告警。"},
    {id:"tool-s04", type:"short", category:"工具命令面试篇", q:"CMake 工程出现“头文件能找到但链接 undefined reference”，你会如何排查？", points:["头文件只提供声明，链接错误说明实现目标未被正确链接或符号不匹配","检查 target_link_libraries、目标可见性、链接顺序和实际生成库","用 nm/readelf 查看符号是否存在及命名是否一致","同时排查 C/C++ linkage、ABI、模板定义位置和编译选项差异"], sample:"能编译说明声明可见，但链接器没找到匹配定义。我会先检查目标是否真的链接了正确库，再用 nm 查看符号；如果库里有类似符号，还要检查 namespace、const、extern C、ABI 以及模板实现是否放在头文件中。"},

    {id:"cuda-s01", type:"short", category:"CUDA 面试篇", q:"请设计一个高效的 CUDA Reduction，并说明从 Block 到 Warp 的优化过程。", points:["每个线程处理一个或多个元素并在寄存器中做局部累加","Block 内使用共享内存或分层规约，减少全局内存访问","最后一个 Warp 可用 shuffle 完成，减少屏障和共享内存","多 Block 结果需要二次 Kernel 或其他全局归约，并处理边界与数值误差"], sample:"我会让线程以 grid-stride loop 做寄存器局部和，再把每个 Warp 的结果用 shuffle 规约；各 Warp 的首线程写入共享内存，最后一个 Warp 再规约这些部分和。Block 结果写到全局内存，由第二个 Kernel 完成最终归约。"},
    {id:"cuda-s02", type:"short", category:"CUDA 面试篇", q:"一个 Kernel 很慢时，你如何判断是计算受限、显存带宽受限还是延迟/同步受限？", points:["先用 Nsight Systems 看时间线、传输、同步和流水线空洞","用 Nsight Compute 查看 DRAM 吞吐、SM 利用率、指令、Stall 与 Occupancy","结合 Roofline 或算术强度判断理论瓶颈","必须在固定输入、硬件、编译参数下对比端到端与 Kernel 指标"], sample:"我先用 Nsight Systems 判断时间是否耗在 Kernel、拷贝或同步，再用 Nsight Compute 查看 DRAM 吞吐、计算管线利用率和 Warp Stall。结合算术强度与 Roofline，才能判断应该优化访存复用、指令效率还是并发隐藏延迟。"},
    {id:"cuda-s03", type:"short", category:"CUDA 面试篇", q:"如何让 H2D、Kernel 和 D2H 在多批数据之间形成流水重叠？", points:["使用多个非默认 Stream，把不同批次操作放入不同 Stream","Host 缓冲区通常需要页锁定内存才能真正异步传输","同一批次在同一 Stream 中保持依赖，不同批次才能重叠","用 Event 表达跨 Stream 依赖并通过时间线验证硬件复制引擎能力"], sample:"可以准备双缓冲或多缓冲，每个缓冲绑定一个非默认 Stream，按 H2D→Kernel→D2H 顺序提交。Host 端使用 pinned memory，并用 Event 管理缓冲复用。是否真正重叠要看 GPU 复制引擎和 Nsight Systems 时间线。"},
    {id:"cuda-s04", type:"short", category:"CUDA 面试篇", q:"设计 CUDA Kernel 的 Grid、Block 和数据映射时，你会重点检查什么？", points:["让相邻线程尽量访问相邻对齐地址，保证合并访存","Block 大小要兼顾 Warp 整数倍、寄存器、共享内存和 Occupancy","检查分支分化、同步范围、边界线程和跨 Block 依赖","用 Profiling 而不是固定经验值决定最终配置"], sample:"我会先从数据布局确定一维或多维线程映射，保证 Warp 内访问连续；Block 通常取 Warp 的整数倍，但还要受寄存器和共享内存限制。随后检查边界、分支和同步，并用不同 Block 配置做基准与 Profiling。"}
  ]
};
